import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  Chip,
  Alert,
  Button
} from '@mui/material';
import {
  Person,
  School,
  Work,
  TrendingUp
} from '@mui/icons-material';
import { useAuth } from '../../context/AuthContext';
import api from '../../services/api';

const CompanyCandidates = () => {
  const { user } = useAuth();
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchCandidates();
  }, []);

  const fetchCandidates = async () => {
    try {
      setLoading(true);
      const response = await api.get('/company/qualified-candidates?minScore=70');
      if (response.data.success) {
        setCandidates(response.data.data.candidates);
      } else {
        setError('Failed to load candidates');
      }
    } catch (err) {
      console.error('Error fetching candidates:', err);
      setError('Error loading candidates');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <Typography>Loading candidates...</Typography>
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h4" gutterBottom>
        Qualified Candidates
      </Typography>
      <Typography variant="body1" color="textSecondary" gutterBottom>
        Top candidates matching your job requirements
      </Typography>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}

      <Grid container spacing={3}>
        {candidates.map((candidate) => (
          <Grid item xs={12} md={6} key={candidate.applicationId}>
            <Card>
              <CardContent>
                <Box display="flex" justifyContent="space-between" alignItems="flex-start" mb={2}>
                  <Box display="flex" alignItems="center">
                    <Person sx={{ mr: 2, color: 'primary.main', fontSize: 40 }} />
                    <Box>
                      <Typography variant="h6">
                        {candidate.studentName}
                      </Typography>
                      <Typography variant="body2" color="textSecondary">
                        {candidate.studentEmail}
                      </Typography>
                    </Box>
                  </Box>
                  <Chip 
                    label={`${candidate.qualificationScore}% Match`}
                    color={candidate.qualificationScore >= 80 ? 'success' : 'warning'}
                  />
                </Box>

                <Typography variant="body2" gutterBottom>
                  Applied for: <strong>{candidate.jobTitle}</strong>
                </Typography>

                <Grid container spacing={1} sx={{ mb: 2 }}>
                  <Grid item xs={6}>
                    <Box display="flex" alignItems="center">
                      <School sx={{ fontSize: 16, mr: 1, color: 'text.secondary' }} />
                      <Typography variant="body2">
                        GPA: {candidate.academicPerformance.averageGPA}
                      </Typography>
                    </Box>
                  </Grid>
                  <Grid item xs={6}>
                    <Box display="flex" alignItems="center">
                      <TrendingUp sx={{ fontSize: 16, mr: 1, color: 'text.secondary' }} />
                      <Typography variant="body2">
                        {candidate.certificatesCount} certs
                      </Typography>
                    </Box>
                  </Grid>
                </Grid>

                <Box display="flex" justifyContent="space-between" alignItems="center">
                  <Typography variant="caption" color="textSecondary">
                    Applied: {new Date(candidate.appliedAt).toLocaleDateString()}
                  </Typography>
                  <Button variant="outlined" size="small">
                    View Profile
                  </Button>
                </Box>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {candidates.length === 0 && (
        <Card>
          <CardContent sx={{ textAlign: 'center', py: 4 }}>
            <Person sx={{ fontSize: 64, color: 'text.secondary', mb: 2 }} />
            <Typography variant="h6" gutterBottom>
              No Qualified Candidates
            </Typography>
            <Typography variant="body2" color="textSecondary">
              No candidates have met the qualification threshold for your job postings yet.
            </Typography>
          </CardContent>
        </Card>
      )}
    </Box>
  );
};

export default CompanyCandidates;