import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Alert,
  Menu,
  MenuItem,
  IconButton,
  Grid
} from '@mui/material';
import {
  MoreVert,
  CheckCircle,
  Cancel,
  Schedule,
  Person
} from '@mui/icons-material';
import { useAuth } from '../../context/AuthContext';
import api from '../../services/api';

const InstituteApplications = () => {
  const { user } = useAuth();
  const [applications, setApplications] = useState([]);
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [actionDialog, setActionDialog] = useState({ open: false, application: null, action: '' });
  const [notes, setNotes] = useState('');

  useEffect(() => {
    fetchApplications();
    fetchCourses();
  }, []);

  const fetchApplications = async () => {
    try {
      setLoading(true);
      const response = await api.get('/institute/applications');
      if (response.data.success) {
        setApplications(response.data.data.applications);
      } else {
        setError('Failed to load applications');
      }
    } catch (err) {
      console.error('Error fetching applications:', err);
      setError('Error loading applications');
    } finally {
      setLoading(false);
    }
  };

  const fetchCourses = async () => {
    try {
      const response = await api.get('/institute/courses');
      if (response.data.success) {
        setCourses(response.data.data.courses);
      }
    } catch (err) {
      console.error('Error fetching courses:', err);
    }
  };

  const handleStatusUpdate = async (applicationId, status) => {
    try {
      const response = await api.patch(`/institute/applications/${applicationId}/status`, {
        status,
        notes: notes || undefined
      });

      if (response.data.success) {
        setSuccess(`Application ${status} successfully`);
        setActionDialog({ open: false, application: null, action: '' });
        setNotes('');
        fetchApplications();
      }
    } catch (err) {
      setError('Error updating application status');
    }
  };

  const handlePublishAdmissions = async (courseId, admittedStudents) => {
    try {
      const response = await api.post('/institute/admissions/publish', {
        courseId,
        admittedStudents
      });

      if (response.data.success) {
        setSuccess('Admissions published successfully');
        fetchApplications();
      }
    } catch (err) {
      setError('Error publishing admissions');
    }
  };

  const getStatusChip = (status) => {
    const statusConfig = {
      pending: { color: 'warning', label: 'Pending' },
      admitted: { color: 'success', label: 'Admitted' },
      rejected: { color: 'error', label: 'Rejected' },
      waiting_list: { color: 'info', label: 'Waiting List' }
    };

    const config = statusConfig[status] || { color: 'default', label: status };
    return <Chip label={config.label} color={config.color} size="small" />;
  };

  const openActionDialog = (application, action) => {
    setActionDialog({ open: true, application, action });
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <Typography>Loading applications...</Typography>
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h4" gutterBottom>
        Student Applications
      </Typography>
      <Typography variant="body1" color="textSecondary" gutterBottom>
        Review and manage student applications for your courses
      </Typography>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
      {success && <Alert severity="success" sx={{ mb: 2 }}>{success}</Alert>}

      <Card>
        <CardContent>
          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Student</TableCell>
                  <TableCell>Course</TableCell>
                  <TableCell>Faculty</TableCell>
                  <TableCell>Applied On</TableCell>
                  <TableCell>Documents</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {applications.map((application) => (
                  <TableRow key={application.id}>
                    <TableCell>
                      <Box display="flex" alignItems="center">
                        <Person sx={{ mr: 2, color: 'primary.main' }} />
                        <Box>
                          <Typography variant="subtitle1">
                            {application.studentName}
                          </Typography>
                          <Typography variant="body2" color="textSecondary">
                            {application.studentEmail}
                          </Typography>
                        </Box>
                      </Box>
                    </TableCell>
                    <TableCell>
                      <Typography variant="body2">
                        {application.courseName}
                      </Typography>
                      <Typography variant="caption" color="textSecondary">
                        {application.courseCode}
                      </Typography>
                    </TableCell>
                    <TableCell>{application.facultyName}</TableCell>
                    <TableCell>
                      {new Date(application.appliedAt).toLocaleDateString()}
                    </TableCell>
                    <TableCell>
                      <Chip 
                        label={`${application.documents?.transcripts || 0} docs`} 
                        variant="outlined" 
                        size="small" 
                      />
                    </TableCell>
                    <TableCell>
                      {getStatusChip(application.status)}
                    </TableCell>
                    <TableCell>
                      <IconButton
                        size="small"
                        onClick={(e) => {
                          const anchorEl = e.currentTarget;
                          // You would implement a menu here for actions
                        }}
                      >
                        <MoreVert />
                      </IconButton>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </CardContent>
      </Card>

      {/* Action Dialog */}
      <Dialog open={actionDialog.open} onClose={() => setActionDialog({ open: false, application: null, action: '' })}>
        <DialogTitle>
          {actionDialog.action === 'admit' ? 'Admit Student' : 
           actionDialog.action === 'reject' ? 'Reject Application' :
           'Update Application Status'}
        </DialogTitle>
        <DialogContent>
          <Typography variant="body1" gutterBottom>
            Student: {actionDialog.application?.studentName}
          </Typography>
          <Typography variant="body2" color="textSecondary" gutterBottom>
            Course: {actionDialog.application?.courseName}
          </Typography>
          
          <TextField
            fullWidth
            label="Notes (Optional)"
            multiline
            rows={3}
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            sx={{ mt: 2 }}
            placeholder="Add any notes or comments about this decision..."
          />

          {actionDialog.action === 'admit' && (
            <Alert severity="info" sx={{ mt: 2 }}>
              <Typography variant="body2">
                Note: Admitting this student will automatically reject their other applications to your institution
                and may move waiting list students if the course is at capacity.
              </Typography>
            </Alert>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setActionDialog({ open: false, application: null, action: '' })}>
            Cancel
          </Button>
          <Button 
            onClick={() => handleStatusUpdate(actionDialog.application.id, actionDialog.action)}
            variant="contained"
            color={actionDialog.action === 'admit' ? 'success' : actionDialog.action === 'reject' ? 'error' : 'primary'}
          >
            Confirm {actionDialog.action}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Bulk Admissions Section */}
      <Card sx={{ mt: 3 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            Bulk Admissions Management
          </Typography>
          <Typography variant="body2" color="textSecondary" gutterBottom>
            Publish admissions for multiple students at once
          </Typography>
          
          <Grid container spacing={2} sx={{ mt: 1 }}>
            {courses.map((course) => (
              <Grid item xs={12} md={6} key={course.id}>
                <Card variant="outlined">
                  <CardContent>
                    <Typography variant="subtitle1" gutterBottom>
                      {course.name}
                    </Typography>
                    <Typography variant="body2" color="textSecondary" gutterBottom>
                      Capacity: {course.currentStudents}/{course.maxStudents}
                    </Typography>
                    <Button 
                      variant="outlined" 
                      size="small"
                      onClick={() => {
                        // Implement bulk admissions for this course
                        const pendingApplications = applications.filter(
                          app => app.courseId === course.id && app.status === 'pending'
                        );
                        if (pendingApplications.length > 0) {
                          const admittedStudents = pendingApplications
                            .slice(0, course.maxStudents - course.currentStudents)
                            .map(app => app.id);
                          
                          if (admittedStudents.length > 0) {
                            handlePublishAdmissions(course.id, admittedStudents);
                          }
                        }
                      }}
                    >
                      Publish Admissions
                    </Button>
                  </CardContent>
                </Card>
              </Grid>
            ))}
          </Grid>
        </CardContent>
      </Card>
    </Box>
  );
};

export default InstituteApplications;