import axios from 'axios';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

console.log('🌐 API Base URL:', API_BASE_URL);

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
  timeout: 15000, // 15 second timeout
});

// Request interceptor to add auth token
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
      console.log('🔐 Adding auth token to request');
    } else {
      console.log('⚠️ No auth token found for request');
    }
    return config;
  },
  (error) => {
    console.error('❌ Request interceptor error:', error);
    return Promise.reject(error);
  }
);

// Response interceptor to handle errors
api.interceptors.response.use(
  (response) => {
    console.log('✅ API Response:', {
      url: response.config.url,
      status: response.status,
      success: response.data?.success
    });
    return response;
  },
  (error) => {
    console.error('❌ API Error:', {
      url: error.config?.url,
      status: error.response?.status,
      message: error.message
    });

    if (error.response?.status === 401) {
      console.log('🔐 Unauthorized, clearing auth data');
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      // Don't redirect here to avoid loops - let components handle it
    }
    
    // Handle network errors
    if (error.code === 'ECONNABORTED') {
      console.error('⏰ Request timeout');
      return Promise.reject(new Error('Request timeout. Please try again.'));
    }
    
    if (!error.response) {
      console.error('🌐 Network error - no response from server');
      return Promise.reject(new Error('Network error. Please check your connection and ensure the backend server is running.'));
    }
    
    // Use server error message if available
    const serverMessage = error.response.data?.message;
    if (serverMessage) {
      return Promise.reject(new Error(serverMessage));
    }
    
    return Promise.reject(error);
  }
);

export default api;