import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  Button,
  Alert,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  IconButton
} from '@mui/material';
import {
  Description,
  Add,
  Delete,
  School,
  WorkspacePremium
} from '@mui/icons-material';
import { useAuth } from '../../context/AuthContext';
import api from '../../services/api';

const StudentDocuments = () => {
  const { user } = useAuth();
  const [documents, setDocuments] = useState({ transcripts: [], certificates: [] });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [dialogOpen, setDialogOpen] = useState({ open: false, type: '' });

  const [formData, setFormData] = useState({
    // Transcript fields
    institutionName: '',
    program: '',
    yearCompleted: '',
    gpa: '',
    // Certificate fields
    name: '',
    issuingOrganization: '',
    issueDate: '',
    expiryDate: ''
  });

  useEffect(() => {
    fetchDocuments();
  }, []);

  const fetchDocuments = async () => {
    try {
      setLoading(true);
      const response = await api.get('/student/documents');
      if (response.data.success) {
        setDocuments(response.data.data);
      } else {
        setError('Failed to load documents');
      }
    } catch (err) {
      console.error('Error fetching documents:', err);
      setError('Error loading documents');
    } finally {
      setLoading(false);
    }
  };

  const handleUpload = async (type) => {
    try {
      let response;
      if (type === 'transcript') {
        response = await api.post('/student/transcripts', {
          ...formData,
          gpa: parseFloat(formData.gpa),
          yearCompleted: parseInt(formData.yearCompleted)
        });
      } else {
        response = await api.post('/student/certificates', {
          ...formData,
          issueDate: new Date(formData.issueDate).toISOString(),
          expiryDate: formData.expiryDate ? new Date(formData.expiryDate).toISOString() : null
        });
      }

      if (response.data.success) {
        setSuccess(`${type === 'transcript' ? 'Transcript' : 'Certificate'} uploaded successfully`);
        setDialogOpen({ open: false, type: '' });
        setFormData({
          institutionName: '',
          program: '',
          yearCompleted: '',
          gpa: '',
          name: '',
          issuingOrganization: '',
          issueDate: '',
          expiryDate: ''
        });
        fetchDocuments();
      }
    } catch (err) {
      setError(`Error uploading ${type}`);
    }
  };

  const openDialog = (type) => {
    setDialogOpen({ open: true, type });
    setFormData({
      institutionName: '',
      program: '',
      yearCompleted: '',
      gpa: '',
      name: '',
      issuingOrganization: '',
      issueDate: '',
      expiryDate: ''
    });
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <Typography>Loading documents...</Typography>
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h4" gutterBottom>
        My Documents
      </Typography>
      <Typography variant="body1" color="textSecondary" gutterBottom>
        Manage your academic transcripts and certificates
      </Typography>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
      {success && <Alert severity="success" sx={{ mb: 2 }}>{success}</Alert>}

      <Grid container spacing={3}>
        {/* Transcripts */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
                <Typography variant="h6">
                  Academic Transcripts
                </Typography>
                <Button
                  variant="contained"
                  startIcon={<Add />}
                  onClick={() => openDialog('transcript')}
                >
                  Add Transcript
                </Button>
              </Box>

              {documents.transcripts.length === 0 ? (
                <Box textAlign="center" py={4}>
                  <School sx={{ fontSize: 48, color: 'text.secondary', mb: 2 }} />
                  <Typography variant="body2" color="textSecondary">
                    No transcripts uploaded yet
                  </Typography>
                </Box>
              ) : (
                <List>
                  {documents.transcripts.map((transcript) => (
                    <ListItem key={transcript.id} divider>
                      <ListItemIcon>
                        <Description color="primary" />
                      </ListItemIcon>
                      <ListItemText
                        primary={transcript.program}
                        secondary={
                          <Box>
                            <Typography variant="body2">
                              {transcript.institutionName}
                            </Typography>
                            <Typography variant="caption" color="textSecondary">
                              Year: {transcript.yearCompleted} • GPA: {transcript.gpa}
                            </Typography>
                          </Box>
                        }
                      />
                      <IconButton edge="end" color="error">
                        <Delete />
                      </IconButton>
                    </ListItem>
                  ))}
                </List>
              )}
            </CardContent>
          </Card>
        </Grid>

        {/* Certificates */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
                <Typography variant="h6">
                  Certificates
                </Typography>
                <Button
                  variant="contained"
                  startIcon={<Add />}
                  onClick={() => openDialog('certificate')}
                >
                  Add Certificate
                </Button>
              </Box>

              {documents.certificates.length === 0 ? (
                <Box textAlign="center" py={4}>
                  <WorkspacePremium sx={{ fontSize: 48, color: 'text.secondary', mb: 2 }} />
                  <Typography variant="body2" color="textSecondary">
                    No certificates uploaded yet
                  </Typography>
                </Box>
              ) : (
                <List>
                  {documents.certificates.map((certificate) => (
                    <ListItem key={certificate.id} divider>
                      <ListItemIcon>
                        <WorkspacePremium color="secondary" />
                      </ListItemIcon>
                      <ListItemText
                        primary={certificate.name}
                        secondary={
                          <Box>
                            <Typography variant="body2">
                              {certificate.issuingOrganization}
                            </Typography>
                            <Typography variant="caption" color="textSecondary">
                              Issued: {new Date(certificate.issueDate).toLocaleDateString()}
                              {certificate.expiryDate && ` • Expires: ${new Date(certificate.expiryDate).toLocaleDateString()}`}
                            </Typography>
                          </Box>
                        }
                      />
                      <IconButton edge="end" color="error">
                        <Delete />
                      </IconButton>
                    </ListItem>
                  ))}
                </List>
              )}
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Upload Dialog */}
      <Dialog open={dialogOpen.open} onClose={() => setDialogOpen({ open: false, type: '' })} maxWidth="sm" fullWidth>
        <DialogTitle>
          {dialogOpen.type === 'transcript' ? 'Upload Transcript' : 'Upload Certificate'}
        </DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            {dialogOpen.type === 'transcript' ? (
              <>
                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label="Institution Name"
                    value={formData.institutionName}
                    onChange={(e) => setFormData({ ...formData, institutionName: e.target.value })}
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label="Program/ Degree"
                    value={formData.program}
                    onChange={(e) => setFormData({ ...formData, program: e.target.value })}
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    label="Year Completed"
                    type="number"
                    value={formData.yearCompleted}
                    onChange={(e) => setFormData({ ...formData, yearCompleted: e.target.value })}
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    label="GPA"
                    type="number"
                    step="0.01"
                    value={formData.gpa}
                    onChange={(e) => setFormData({ ...formData, gpa: e.target.value })}
                  />
                </Grid>
              </>
            ) : (
              <>
                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label="Certificate Name"
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label="Issuing Organization"
                    value={formData.issuingOrganization}
                    onChange={(e) => setFormData({ ...formData, issuingOrganization: e.target.value })}
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    label="Issue Date"
                    type="date"
                    InputLabelProps={{ shrink: true }}
                    value={formData.issueDate}
                    onChange={(e) => setFormData({ ...formData, issueDate: e.target.value })}
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    label="Expiry Date (Optional)"
                    type="date"
                    InputLabelProps={{ shrink: true }}
                    value={formData.expiryDate}
                    onChange={(e) => setFormData({ ...formData, expiryDate: e.target.value })}
                  />
                </Grid>
              </>
            )}
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDialogOpen({ open: false, type: '' })}>Cancel</Button>
          <Button 
            onClick={() => handleUpload(dialogOpen.type)}
            variant="contained"
          >
            Upload {dialogOpen.type === 'transcript' ? 'Transcript' : 'Certificate'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default StudentDocuments;