import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Grid,
  Card,
  CardContent,
  Alert,
  LinearProgress
} from '@mui/material';
import {
  People,
  School,
  Business,
  TrendingUp,
  Assignment,
  Work
} from '@mui/icons-material';
import { useAuth } from '../../context/AuthContext';
import api from '../../services/api';

const StatCard = ({ title, value, subtitle, icon, color = 'primary' }) => (
  <Card>
    <CardContent>
      <Box display="flex" alignItems="center" justifyContent="space-between">
        <Box>
          <Typography color="textSecondary" gutterBottom variant="overline">
            {title}
          </Typography>
          <Typography variant="h4" component="div">
            {value}
          </Typography>
          {subtitle && (
            <Typography variant="body2" color="textSecondary">
              {subtitle}
            </Typography>
          )}
        </Box>
        <Box
          sx={{
            backgroundColor: `${color}.light`,
            borderRadius: '50%',
            p: 1,
            color: 'white',
          }}
        >
          {icon}
        </Box>
      </Box>
    </CardContent>
  </Card>
);

const AdminDashboard = () => {
  const { user } = useAuth();
  const [dashboardData, setDashboardData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const response = await api.get('/admin/dashboard');
      if (response.data.success) {
        setDashboardData(response.data.data);
      } else {
        setError('Failed to load dashboard data');
      }
    } catch (err) {
      console.error('Error fetching dashboard:', err);
      setError('Error loading dashboard data');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <LinearProgress sx={{ width: '100%' }} />
      </Box>
    );
  }

  if (error) {
    return (
      <Alert severity="error" sx={{ mb: 2 }}>
        {error}
      </Alert>
    );
  }

  if (!dashboardData) {
    return (
      <Alert severity="warning">
        No dashboard data available
      </Alert>
    );
  }

  const { stats, pendingApprovals } = dashboardData;

  return (
    <Box>
      <Typography variant="h4" gutterBottom>
        Admin Dashboard
      </Typography>
      <Typography variant="body1" color="textSecondary" gutterBottom>
        System Overview and Management
      </Typography>

      {/* Quick Stats */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Total Users"
            value={stats.totalUsers}
            subtitle={`${stats.totalStudents} students`}
            icon={<People />}
            color="primary"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Institutions"
            value={stats.totalInstitutions}
            subtitle={`${pendingApprovals?.institutions?.length || 0} pending`}
            icon={<School />}
            color="secondary"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Companies"
            value={stats.totalCompanies}
            subtitle={`${pendingApprovals?.companies?.length || 0} pending`}
            icon={<Business />}
            color="success"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Applications"
            value={stats.totalApplications}
            subtitle="Across system"
            icon={<Assignment />}
            color="warning"
          />
        </Grid>
      </Grid>

      {/* Pending Approvals */}
      {(pendingApprovals?.institutions?.length > 0 || pendingApprovals?.companies?.length > 0) && (
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Typography variant="h6" gutterBottom>
              Pending Approvals
            </Typography>
            <Grid container spacing={2}>
              {pendingApprovals.institutions.length > 0 && (
                <Grid item xs={12} md={6}>
                  <Typography variant="subtitle1" gutterBottom>
                    Institutions ({pendingApprovals.institutions.length})
                  </Typography>
                  {pendingApprovals.institutions.slice(0, 3).map((inst) => (
                    <Box key={inst.id} sx={{ mb: 1, p: 1, bgcolor: 'grey.50', borderRadius: 1 }}>
                      <Typography variant="body2">{inst.name}</Typography>
                      <Typography variant="caption" color="textSecondary">
                        {inst.email}
                      </Typography>
                    </Box>
                  ))}
                </Grid>
              )}
              {pendingApprovals.companies.length > 0 && (
                <Grid item xs={12} md={6}>
                  <Typography variant="subtitle1" gutterBottom>
                    Companies ({pendingApprovals.companies.length})
                  </Typography>
                  {pendingApprovals.companies.slice(0, 3).map((company) => (
                    <Box key={company.id} sx={{ mb: 1, p: 1, bgcolor: 'grey.50', borderRadius: 1 }}>
                      <Typography variant="body2">{company.name}</Typography>
                      <Typography variant="caption" color="textSecondary">
                        {company.email}
                      </Typography>
                    </Box>
                  ))}
                </Grid>
              )}
            </Grid>
          </CardContent>
        </Card>
      )}

      {/* System Health */}
      <Card>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            System Health
          </Typography>
          <Grid container spacing={3}>
            <Grid item xs={12} sm={4}>
              <Box textAlign="center">
                <TrendingUp sx={{ fontSize: 48, color: 'success.main', mb: 1 }} />
                <Typography variant="h6">Operational</Typography>
                <Typography variant="body2" color="textSecondary">
                  All systems normal
                </Typography>
              </Box>
            </Grid>
            <Grid item xs={12} sm={4}>
              <Box textAlign="center">
                <Work sx={{ fontSize: 48, color: 'primary.main', mb: 1 }} />
                <Typography variant="h6">{stats.activeJobs}</Typography>
                <Typography variant="body2" color="textSecondary">
                  Active Jobs
                </Typography>
              </Box>
            </Grid>
            <Grid item xs={12} sm={4}>
              <Box textAlign="center">
                <School sx={{ fontSize: 48, color: 'secondary.main', mb: 1 }} />
                <Typography variant="h6">{stats.courses}</Typography>
                <Typography variant="body2" color="textSecondary">
                  Total Courses
                </Typography>
              </Box>
            </Grid>
          </Grid>
        </CardContent>
      </Card>
    </Box>
  );
};

export default AdminDashboard;