import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  IconButton,
  Menu,
  MenuItem,
  Alert
} from '@mui/material';
import {
  MoreVert,
  CheckCircle,
  Block,
  Business
} from '@mui/icons-material';
import { useAuth } from '../../context/AuthContext';
import api from '../../services/api';

const AdminCompanies = () => {
  const { user } = useAuth();
  const [companies, setCompanies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [anchorEl, setAnchorEl] = useState(null);
  const [selectedCompany, setSelectedCompany] = useState(null);

  useEffect(() => {
    fetchCompanies();
  }, []);

  const fetchCompanies = async () => {
    try {
      setLoading(true);
      const response = await api.get('/admin/companies');
      if (response.data.success) {
        setCompanies(response.data.data.companies);
      } else {
        setError('Failed to load companies');
      }
    } catch (err) {
      console.error('Error fetching companies:', err);
      setError('Error loading companies');
    } finally {
      setLoading(false);
    }
  };

  const handleMenuOpen = (event, company) => {
    setAnchorEl(event.currentTarget);
    setSelectedCompany(company);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
    setSelectedCompany(null);
  };

  const handleApprove = async (companyId) => {
    try {
      const response = await api.post(`/admin/approve/${companyId}`, {
        type: 'company'
      });
      if (response.data.success) {
        setSuccess('Company approved successfully');
        fetchCompanies();
      }
    } catch (err) {
      setError('Error approving company');
    }
    handleMenuClose();
  };

  const handleSuspend = async (companyId, action) => {
    try {
      const response = await api.patch(`/admin/users/${companyId}/status`, {
        action: action ? 'activate' : 'suspend'
      });
      if (response.data.success) {
        setSuccess(`Company ${action ? 'activated' : 'suspended'} successfully`);
        fetchCompanies();
      }
    } catch (err) {
      setError('Error updating company status');
    }
    handleMenuClose();
  };

  const getStatusChip = (company) => {
    if (!company.isApproved) {
      return <Chip label="Pending Approval" color="warning" size="small" />;
    }
    if (!company.isActive) {
      return <Chip label="Suspended" color="error" size="small" />;
    }
    return <Chip label="Active" color="success" size="small" />;
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <Typography>Loading companies...</Typography>
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h4" gutterBottom>
        Manage Companies
      </Typography>
      <Typography variant="body1" color="textSecondary" gutterBottom>
        Approve and manage company accounts
      </Typography>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
      {success && <Alert severity="success" sx={{ mb: 2 }}>{success}</Alert>}

      <Card>
        <CardContent>
          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Company Name</TableCell>
                  <TableCell>Email</TableCell>
                  <TableCell>Industry</TableCell>
                  <TableCell>Jobs</TableCell>
                  <TableCell>Applications</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {companies.map((company) => (
                  <TableRow key={company.id}>
                    <TableCell>
                      <Box display="flex" alignItems="center">
                        <Business sx={{ mr: 2, color: 'primary.main' }} />
                        <Box>
                          <Typography variant="subtitle1">
                            {company.companyName}
                          </Typography>
                          <Typography variant="body2" color="textSecondary">
                            {company.industry}
                          </Typography>
                        </Box>
                      </Box>
                    </TableCell>
                    <TableCell>{company.email}</TableCell>
                    <TableCell>{company.industry}</TableCell>
                    <TableCell>
                      <Chip 
                        label={company.stats?.totalJobs || 0} 
                        variant="outlined" 
                        size="small" 
                      />
                    </TableCell>
                    <TableCell>
                      <Chip 
                        label={company.stats?.totalApplications || 0} 
                        variant="outlined" 
                        size="small" 
                      />
                    </TableCell>
                    <TableCell>
                      {getStatusChip(company)}
                    </TableCell>
                    <TableCell>
                      <IconButton
                        size="small"
                        onClick={(e) => handleMenuOpen(e, company)}
                      >
                        <MoreVert />
                      </IconButton>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </CardContent>
      </Card>

      {/* Actions Menu */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleMenuClose}
      >
        {!selectedCompany?.isApproved && (
          <MenuItem onClick={() => handleApprove(selectedCompany?.id)}>
            <CheckCircle sx={{ mr: 1 }} />
            Approve
          </MenuItem>
        )}
        <MenuItem onClick={() => handleSuspend(selectedCompany?.id, !selectedCompany?.isActive)}>
          <Block sx={{ mr: 1 }} />
          {selectedCompany?.isActive ? 'Suspend' : 'Activate'}
        </MenuItem>
      </Menu>
    </Box>
  );
};

export default AdminCompanies;