import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Alert,
  Grid,
  Menu,
  MenuItem,
  FormControl,
  InputLabel,
  Select
} from '@mui/material';
import {
  Add,
  MoreVert,
  Edit,
  Delete,
  Work,
  Business
} from '@mui/icons-material';
import { useAuth } from '../../context/AuthContext';
import api from '../../services/api';

const CompanyJobs = () => {
  const { user } = useAuth();
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [dialogOpen, setDialogOpen] = useState(false);
  const [anchorEl, setAnchorEl] = useState(null);
  const [selectedJob, setSelectedJob] = useState(null);

  const [formData, setFormData] = useState({
    title: '',
    department: '',
    description: '',
    requirements: [''],
    responsibilities: [''],
    qualifications: {
      minEducation: '',
      requiredSkills: [''],
      minExperience: ''
    },
    location: '',
    jobType: 'full-time',
    salaryRange: {
      min: '',
      max: '',
      currency: 'LSL'
    },
    deadline: '',
    positionsAvailable: ''
  });

  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = async () => {
    try {
      setLoading(true);
      const response = await api.get('/company/jobs');
      if (response.data.success) {
        setJobs(response.data.data.jobs);
      } else {
        setError('Failed to load jobs');
      }
    } catch (err) {
      console.error('Error fetching jobs:', err);
      setError('Error loading jobs');
    } finally {
      setLoading(false);
    }
  };

  const handleMenuOpen = (event, job) => {
    setAnchorEl(event.currentTarget);
    setSelectedJob(job);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
    setSelectedJob(null);
  };

  const handleAddJob = async () => {
    try {
      const jobData = {
        ...formData,
        positionsAvailable: parseInt(formData.positionsAvailable),
        salaryRange: {
          min: parseFloat(formData.salaryRange.min),
          max: parseFloat(formData.salaryRange.max),
          currency: formData.salaryRange.currency
        },
        deadline: new Date(formData.deadline).toISOString(),
        requirements: formData.requirements.filter(req => req.trim() !== ''),
        responsibilities: formData.responsibilities.filter(resp => resp.trim() !== ''),
        qualifications: {
          ...formData.qualifications,
          requiredSkills: formData.qualifications.requiredSkills.filter(skill => skill.trim() !== '')
        }
      };

      const response = await api.post('/company/jobs', jobData);
      if (response.data.success) {
        setSuccess('Job posted successfully! Qualified students will be notified.');
        setDialogOpen(false);
        setFormData({
          title: '',
          department: '',
          description: '',
          requirements: [''],
          responsibilities: [''],
          qualifications: {
            minEducation: '',
            requiredSkills: [''],
            minExperience: ''
          },
          location: '',
          jobType: 'full-time',
          salaryRange: {
            min: '',
            max: '',
            currency: 'LSL'
          },
          deadline: '',
          positionsAvailable: ''
        });
        fetchJobs();
      }
    } catch (err) {
      setError('Error creating job posting');
    }
  };

  const handleCloseJob = async (jobId) => {
    try {
      const response = await api.patch(`/company/jobs/${jobId}/close`, {
        reason: 'Position filled'
      });
      if (response.data.success) {
        setSuccess('Job closed successfully');
        fetchJobs();
      }
    } catch (err) {
      setError('Error closing job');
    }
    handleMenuClose();
  };

  const addRequirement = () => {
    setFormData({
      ...formData,
      requirements: [...formData.requirements, '']
    });
  };

  const updateRequirement = (index, value) => {
    const newRequirements = [...formData.requirements];
    newRequirements[index] = value;
    setFormData({ ...formData, requirements: newRequirements });
  };

  const removeRequirement = (index) => {
    const newRequirements = formData.requirements.filter((_, i) => i !== index);
    setFormData({ ...formData, requirements: newRequirements });
  };

  const addResponsibility = () => {
    setFormData({
      ...formData,
      responsibilities: [...formData.responsibilities, '']
    });
  };

  const updateResponsibility = (index, value) => {
    const newResponsibilities = [...formData.responsibilities];
    newResponsibilities[index] = value;
    setFormData({ ...formData, responsibilities: newResponsibilities });
  };

  const removeResponsibility = (index) => {
    const newResponsibilities = formData.responsibilities.filter((_, i) => i !== index);
    setFormData({ ...formData, responsibilities: newResponsibilities });
  };

  const addSkill = () => {
    setFormData({
      ...formData,
      qualifications: {
        ...formData.qualifications,
        requiredSkills: [...formData.qualifications.requiredSkills, '']
      }
    });
  };

  const updateSkill = (index, value) => {
    const newSkills = [...formData.qualifications.requiredSkills];
    newSkills[index] = value;
    setFormData({
      ...formData,
      qualifications: {
        ...formData.qualifications,
        requiredSkills: newSkills
      }
    });
  };

  const removeSkill = (index) => {
    const newSkills = formData.qualifications.requiredSkills.filter((_, i) => i !== index);
    setFormData({
      ...formData,
      qualifications: {
        ...formData.qualifications,
        requiredSkills: newSkills
      }
    });
  };

  const getStatusChip = (job) => {
    if (job.status === 'active') {
      return <Chip label="Active" color="success" size="small" />;
    } else if (job.status === 'closed') {
      return <Chip label="Closed" color="default" size="small" />;
    }
    return <Chip label="Draft" color="warning" size="small" />;
  };

  const getCapacityColor = (job) => {
    const percentage = (job.positionsFilled / job.positionsAvailable) * 100;
    if (percentage >= 90) return 'error';
    if (percentage >= 70) return 'warning';
    return 'success';
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <Typography>Loading jobs...</Typography>
      </Box>
    );
  }

  return (
    <Box>
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h4" gutterBottom>
          Manage Job Postings
        </Typography>
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={() => setDialogOpen(true)}
        >
          Post New Job
        </Button>
      </Box>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
      {success && <Alert severity="success" sx={{ mb: 2 }}>{success}</Alert>}

      <Card>
        <CardContent>
          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Job Title</TableCell>
                  <TableCell>Department</TableCell>
                  <TableCell>Type</TableCell>
                  <TableCell>Location</TableCell>
                  <TableCell>Applications</TableCell>
                  <TableCell>Positions</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {jobs.map((job) => (
                  <TableRow key={job.id}>
                    <TableCell>
                      <Box display="flex" alignItems="center">
                        <Work sx={{ mr: 2, color: 'primary.main' }} />
                        <Box>
                          <Typography variant="subtitle1">
                            {job.title}
                          </Typography>
                          <Typography variant="body2" color="textSecondary">
                            {job.department}
                          </Typography>
                        </Box>
                      </Box>
                    </TableCell>
                    <TableCell>{job.department}</TableCell>
                    <TableCell>
                      <Chip 
                        label={job.jobType} 
                        variant="outlined" 
                        size="small" 
                      />
                    </TableCell>
                    <TableCell>{job.location}</TableCell>
                    <TableCell>
                      <Box>
                        <Typography variant="body2">
                          Total: {job.stats?.totalApplications || 0}
                        </Typography>
                        <Typography variant="caption" color="textSecondary">
                          Qualified: {job.stats?.qualifiedApplications || 0}
                        </Typography>
                      </Box>
                    </TableCell>
                    <TableCell>
                      <Chip 
                        label={`${job.positionsFilled}/${job.positionsAvailable}`}
                        color={getCapacityColor(job)}
                        size="small" 
                      />
                    </TableCell>
                    <TableCell>
                      {getStatusChip(job)}
                    </TableCell>
                    <TableCell>
                      <IconButton
                        size="small"
                        onClick={(e) => handleMenuOpen(e, job)}
                      >
                        <MoreVert />
                      </IconButton>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </CardContent>
      </Card>

      {/* Add Job Dialog */}
      <Dialog open={dialogOpen} onClose={() => setDialogOpen(false)} maxWidth="lg" fullWidth>
        <DialogTitle>Post New Job</DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Job Title"
                value={formData.title}
                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Department"
                value={formData.department}
                onChange={(e) => setFormData({ ...formData, department: e.target.value })}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Job Description"
                multiline
                rows={3}
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Location"
                value={formData.location}
                onChange={(e) => setFormData({ ...formData, location: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Job Type</InputLabel>
                <Select
                  value={formData.jobType}
                  label="Job Type"
                  onChange={(e) => setFormData({ ...formData, jobType: e.target.value })}
                >
                  <MenuItem value="full-time">Full Time</MenuItem>
                  <MenuItem value="part-time">Part Time</MenuItem>
                  <MenuItem value="contract">Contract</MenuItem>
                  <MenuItem value="internship">Internship</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={4}>
              <TextField
                fullWidth
                label="Salary Min (M)"
                type="number"
                value={formData.salaryRange.min}
                onChange={(e) => setFormData({ 
                  ...formData, 
                  salaryRange: { ...formData.salaryRange, min: e.target.value } 
                })}
              />
            </Grid>
            <Grid item xs={12} sm={4}>
              <TextField
                fullWidth
                label="Salary Max (M)"
                type="number"
                value={formData.salaryRange.max}
                onChange={(e) => setFormData({ 
                  ...formData, 
                  salaryRange: { ...formData.salaryRange, max: e.target.value } 
                })}
              />
            </Grid>
            <Grid item xs={12} sm={4}>
              <TextField
                fullWidth
                label="Positions Available"
                type="number"
                value={formData.positionsAvailable}
                onChange={(e) => setFormData({ ...formData, positionsAvailable: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Application Deadline"
                type="date"
                InputLabelProps={{ shrink: true }}
                value={formData.deadline}
                onChange={(e) => setFormData({ ...formData, deadline: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Minimum Education</InputLabel>
                <Select
                  value={formData.qualifications.minEducation}
                  label="Minimum Education"
                  onChange={(e) => setFormData({
                    ...formData,
                    qualifications: { ...formData.qualifications, minEducation: e.target.value }
                  })}
                >
                  <MenuItem value="High School">High School</MenuItem>
                  <MenuItem value="Diploma">Diploma</MenuItem>
                  <MenuItem value="Bachelor's Degree">Bachelor's Degree</MenuItem>
                  <MenuItem value="Master's Degree">Master's Degree</MenuItem>
                  <MenuItem value="PhD">PhD</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Minimum Experience"
                value={formData.qualifications.minExperience}
                onChange={(e) => setFormData({
                  ...formData,
                  qualifications: { ...formData.qualifications, minExperience: e.target.value }
                })}
                placeholder="e.g., 2-3 years"
              />
            </Grid>

            {/* Requirements */}
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom>
                Requirements
              </Typography>
              {formData.requirements.map((requirement, index) => (
                <Box key={index} display="flex" gap={1} mb={1}>
                  <TextField
                    fullWidth
                    value={requirement}
                    onChange={(e) => updateRequirement(index, e.target.value)}
                    placeholder="Enter requirement"
                  />
                  <Button
                    color="error"
                    onClick={() => removeRequirement(index)}
                    disabled={formData.requirements.length === 1}
                  >
                    Remove
                  </Button>
                </Box>
              ))}
              <Button onClick={addRequirement} variant="outlined">
                Add Requirement
              </Button>
            </Grid>

            {/* Responsibilities */}
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom>
                Responsibilities
              </Typography>
              {formData.responsibilities.map((responsibility, index) => (
                <Box key={index} display="flex" gap={1} mb={1}>
                  <TextField
                    fullWidth
                    value={responsibility}
                    onChange={(e) => updateResponsibility(index, e.target.value)}
                    placeholder="Enter responsibility"
                  />
                  <Button
                    color="error"
                    onClick={() => removeResponsibility(index)}
                    disabled={formData.responsibilities.length === 1}
                  >
                    Remove
                  </Button>
                </Box>
              ))}
              <Button onClick={addResponsibility} variant="outlined">
                Add Responsibility
              </Button>
            </Grid>

            {/* Required Skills */}
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom>
                Required Skills
              </Typography>
              {formData.qualifications.requiredSkills.map((skill, index) => (
                <Box key={index} display="flex" gap={1} mb={1}>
                  <TextField
                    fullWidth
                    value={skill}
                    onChange={(e) => updateSkill(index, e.target.value)}
                    placeholder="Enter required skill"
                  />
                  <Button
                    color="error"
                    onClick={() => removeSkill(index)}
                    disabled={formData.qualifications.requiredSkills.length === 1}
                  >
                    Remove
                  </Button>
                </Box>
              ))}
              <Button onClick={addSkill} variant="outlined">
                Add Skill
              </Button>
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDialogOpen(false)}>Cancel</Button>
          <Button onClick={handleAddJob} variant="contained">
            Post Job
          </Button>
        </DialogActions>
      </Dialog>

      {/* Actions Menu */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleMenuClose}
      >
        <MenuItem onClick={() => { handleMenuClose(); /* Navigate to applications */ }}>
          <Business sx={{ mr: 1 }} />
          View Applications
        </MenuItem>
        <MenuItem onClick={handleMenuClose}>
          <Edit sx={{ mr: 1 }} />
          Edit
        </MenuItem>
        {selectedJob?.status === 'active' && (
          <MenuItem onClick={() => handleCloseJob(selectedJob?.id)}>
            <Delete sx={{ mr: 1 }} />
            Close Job
          </MenuItem>
        )}
      </Menu>
    </Box>
  );
};

export default CompanyJobs;