import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  Chip,
  Alert,
  Button,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem
} from '@mui/material';
import {
  Business,
  TrendingUp,
  Schedule,
  LocationOn
} from '@mui/icons-material';
import { useAuth } from '../../context/AuthContext';
import api from '../../services/api';

const StudentJobs = () => {
  const { user } = useAuth();
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const [filters, setFilters] = useState({
    search: '',
    jobType: 'all',
    location: 'all'
  });

  useEffect(() => {
    fetchJobs();
  }, [filters]);

  const fetchJobs = async () => {
    try {
      setLoading(true);
      const queryParams = new URLSearchParams();
      Object.entries(filters).forEach(([key, value]) => {
        if (value !== 'all' && value !== '') {
          queryParams.append(key, value);
        }
      });

      const response = await api.get(`/student/jobs?${queryParams}`);
      if (response.data.success) {
        setJobs(response.data.data.jobs);
      } else {
        setError('Failed to load jobs');
      }
    } catch (err) {
      console.error('Error fetching jobs:', err);
      setError('Error loading jobs');
    } finally {
      setLoading(false);
    }
  };

  const handleApply = async (jobId) => {
    try {
      const response = await api.post('/student/job-applications', {
        jobId,
        coverLetter: 'I am interested in this position and believe my qualifications are a good match.'
      });

      if (response.data.success) {
        setSuccess('Application submitted successfully!');
        fetchJobs(); // Refresh to update application status
      } else {
        setError(response.data.message || 'Failed to submit application');
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Error submitting application');
    }
  };

  const getActionButton = (job) => {
    if (job.hasApplied) {
      return (
        <Button variant="outlined" disabled size="small">
          Already Applied
        </Button>
      );
    }

    if (!job.isQualified) {
      return (
        <Button variant="outlined" disabled size="small">
          Not Qualified
        </Button>
      );
    }

    return (
      <Button
        variant="contained"
        size="small"
        onClick={() => handleApply(job.id)}
      >
        Apply Now
      </Button>
    );
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <Typography>Loading jobs...</Typography>
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h4" gutterBottom>
        Job Opportunities
      </Typography>
      <Typography variant="body1" color="textSecondary" gutterBottom>
        Browse and apply for jobs matching your profile
      </Typography>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
      {success && <Alert severity="success" sx={{ mb: 2 }}>{success}</Alert>}

      {/* Filters */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={4}>
              <TextField
                fullWidth
                label="Search Jobs"
                value={filters.search}
                onChange={(e) => setFilters({ ...filters, search: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={4}>
              <FormControl fullWidth>
                <InputLabel>Job Type</InputLabel>
                <Select
                  value={filters.jobType}
                  label="Job Type"
                  onChange={(e) => setFilters({ ...filters, jobType: e.target.value })}
                >
                  <MenuItem value="all">All Types</MenuItem>
                  <MenuItem value="full-time">Full Time</MenuItem>
                  <MenuItem value="part-time">Part Time</MenuItem>
                  <MenuItem value="contract">Contract</MenuItem>
                  <MenuItem value="internship">Internship</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={4}>
              <Button
                variant="outlined"
                onClick={() => setFilters({
                  search: '',
                  jobType: 'all',
                  location: 'all'
                })}
                fullWidth
                sx={{ height: '56px' }}
              >
                Clear Filters
              </Button>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* Jobs Grid */}
      <Grid container spacing={3}>
        {jobs.map((job) => (
          <Grid item xs={12} md={6} key={job.id}>
            <Card 
              sx={{ 
                height: '100%',
                border: job.hasApplied ? '2px solid' : '1px solid',
                borderColor: job.hasApplied ? 'primary.main' : 'divider'
              }}
            >
              <CardContent>
                <Box display="flex" justifyContent="space-between" alignItems="flex-start" mb={2}>
                  <Box>
                    <Typography variant="h6" gutterBottom>
                      {job.title}
                    </Typography>
                    <Typography variant="body2" color="textSecondary" gutterBottom>
                      {job.companyName}
                    </Typography>
                    <Typography variant="body2" color="textSecondary">
                      {job.department}
                    </Typography>
                  </Box>
                  {job.hasApplied && (
                    <Chip label="Applied" color="success" size="small" />
                  )}
                </Box>

                <Typography variant="body2" sx={{ mb: 2 }}>
                  {job.description?.substring(0, 150)}...
                </Typography>

                <Grid container spacing={1} sx={{ mb: 2 }}>
                  <Grid item xs={6}>
                    <Box display="flex" alignItems="center">
                      <LocationOn sx={{ fontSize: 16, mr: 1, color: 'text.secondary' }} />
                      <Typography variant="body2">
                        {job.location}
                      </Typography>
                    </Box>
                  </Grid>
                  <Grid item xs={6}>
                    <Box display="flex" alignItems="center">
                      <Schedule sx={{ fontSize: 16, mr: 1, color: 'text.secondary' }} />
                      <Typography variant="body2">
                        {job.jobType}
                      </Typography>
                    </Box>
                  </Grid>
                  <Grid item xs={6}>
                    <Typography variant="body2" color="textSecondary">
                      Applications: {job.applicationsCount}
                    </Typography>
                  </Grid>
                  <Grid item xs={6}>
                    <Typography 
                      variant="body2" 
                      color={job.isQualified ? 'success.main' : 'error.main'}
                    >
                      Match: {job.qualificationScore}%
                    </Typography>
                  </Grid>
                </Grid>

                {job.salaryRange && (
                  <Typography variant="body2" color="primary" gutterBottom>
                    Salary: M{job.salaryRange.min?.toLocaleString()} - M{job.salaryRange.max?.toLocaleString()}
                  </Typography>
                )}

                <Box display="flex" justifyContent="space-between" alignItems="center">
                  <Typography variant="caption" color="textSecondary">
                    Deadline: {new Date(job.deadline).toLocaleDateString()}
                  </Typography>
                  {getActionButton(job)}
                </Box>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {jobs.length === 0 && !loading && (
        <Box textAlign="center" py={4}>
          <Business sx={{ fontSize: 64, color: 'text.secondary', mb: 2 }} />
          <Typography variant="h6" color="textSecondary">
            No jobs found matching your criteria
          </Typography>
        </Box>
      )}
    </Box>
  );
};

export default StudentJobs;