import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Button,
  Grid,
  Chip,
  Alert,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  LinearProgress
} from '@mui/material';
import {
  School,
  Business,
  TrendingUp,
  Schedule,
  Apply
} from '@mui/icons-material';
import { useAuth } from '../../context/AuthContext';
import api from '../../services/api';

const StudentCourses = () => {
  const { user } = useAuth();
  const [courses, setCourses] = useState([]);
  const [institutions, setInstitutions] = useState([]);
  const [faculties, setFaculties] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [applyDialogOpen, setApplyDialogOpen] = useState(false);
  const [selectedCourse, setSelectedCourse] = useState(null);

  const [filters, setFilters] = useState({
    search: '',
    institutionId: 'all',
    faculty: 'all',
    minFee: 0,
    maxFee: 100000
  });

  const [applicationData, setApplicationData] = useState({
    personalStatement: '',
    additionalInfo: ''
  });

  useEffect(() => {
    fetchCourses();
    fetchInstitutions();
    fetchFaculties();
  }, [filters]);

  const fetchCourses = async () => {
    try {
      setLoading(true);
      const queryParams = new URLSearchParams();
      Object.entries(filters).forEach(([key, value]) => {
        if (value !== 'all' && value !== '') {
          queryParams.append(key, value);
        }
      });

      const response = await api.get(`/student/courses?${queryParams}`);
      if (response.data.success) {
        setCourses(response.data.data.courses);
      } else {
        setError('Failed to load courses');
      }
    } catch (err) {
      console.error('Error fetching courses:', err);
      setError('Error loading courses');
    } finally {
      setLoading(false);
    }
  };

  const fetchInstitutions = async () => {
    try {
      const response = await api.get('/student/institutions');
      if (response.data.success) {
        setInstitutions(response.data.data.institutions);
      }
    } catch (err) {
      console.error('Error fetching institutions:', err);
    }
  };

  const fetchFaculties = async () => {
    try {
      const response = await api.get('/student/faculties');
      if (response.data.success) {
        setFaculties(response.data.data.faculties);
      }
    } catch (err) {
      console.error('Error fetching faculties:', err);
    }
  };

  const handleApply = (course) => {
    setSelectedCourse(course);
    setApplicationData({
      personalStatement: '',
      additionalInfo: ''
    });
    setApplyDialogOpen(true);
  };

  const handleSubmitApplication = async () => {
    try {
      const response = await api.post('/student/applications', {
        courseId: selectedCourse.id,
        ...applicationData
      });

      if (response.data.success) {
        setSuccess('Application submitted successfully!');
        setApplyDialogOpen(false);
        fetchCourses(); // Refresh to update application status
      } else {
        setError(response.data.message || 'Failed to submit application');
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Error submitting application');
    }
  };

  const getApplicationStatus = (course) => {
    if (course.hasApplied) {
      return (
        <Chip
          label={course.applicationStatus}
          color={
            course.applicationStatus === 'admitted' ? 'success' :
            course.applicationStatus === 'rejected' ? 'error' : 'warning'
          }
        />
      );
    }
    return null;
  };

  const getActionButton = (course) => {
    if (course.hasApplied) {
      return (
        <Button variant="outlined" disabled>
          Already Applied
        </Button>
      );
    }

    if (!course.canApply) {
      return (
        <Button variant="outlined" disabled>
          Not Qualified
        </Button>
      );
    }

    return (
      <Button
        variant="contained"
        onClick={() => handleApply(course)}
        disabled={course.spotsLeft <= 0}
      >
        {course.spotsLeft <= 0 ? 'Course Full' : 'Apply Now'}
      </Button>
    );
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <LinearProgress sx={{ width: '100%' }} />
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h4" gutterBottom>
        Browse Available Courses
      </Typography>
      <Typography variant="body1" color="textSecondary" gutterBottom>
        Explore courses from various institutions and apply (maximum 2 courses per institution)
      </Typography>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
      {success && <Alert severity="success" sx={{ mb: 2 }}>{success}</Alert>}

      {/* Filters */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={3}>
              <TextField
                fullWidth
                label="Search Courses"
                value={filters.search}
                onChange={(e) => setFilters({ ...filters, search: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={3}>
              <FormControl fullWidth>
                <InputLabel>Institution</InputLabel>
                <Select
                  value={filters.institutionId}
                  label="Institution"
                  onChange={(e) => setFilters({ ...filters, institutionId: e.target.value })}
                >
                  <MenuItem value="all">All Institutions</MenuItem>
                  {institutions.map((inst) => (
                    <MenuItem key={inst.id} value={inst.id}>
                      {inst.name}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={3}>
              <FormControl fullWidth>
                <InputLabel>Faculty</InputLabel>
                <Select
                  value={filters.faculty}
                  label="Faculty"
                  onChange={(e) => setFilters({ ...filters, faculty: e.target.value })}
                >
                  <MenuItem value="all">All Faculties</MenuItem>
                  {faculties.map((faculty) => (
                    <MenuItem key={faculty.id} value={faculty.id}>
                      {faculty.name}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={3}>
              <Button
                variant="outlined"
                onClick={() => setFilters({
                  search: '',
                  institutionId: 'all',
                  faculty: 'all',
                  minFee: 0,
                  maxFee: 100000
                })}
                fullWidth
                sx={{ height: '56px' }}
              >
                Clear Filters
              </Button>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* Courses Grid */}
      <Grid container spacing={3}>
        {courses.map((course) => (
          <Grid item xs={12} md={6} key={course.id}>
            <Card 
              sx={{ 
                height: '100%',
                border: course.hasApplied ? '2px solid' : '1px solid',
                borderColor: course.hasApplied ? 'primary.main' : 'divider'
              }}
            >
              <CardContent>
                <Box display="flex" justifyContent="space-between" alignItems="flex-start" mb={2}>
                  <Box>
                    <Typography variant="h6" gutterBottom>
                      {course.name}
                    </Typography>
                    <Typography variant="body2" color="textSecondary" gutterBottom>
                      {course.code} • {course.instituteName}
                    </Typography>
                    <Typography variant="body2" color="textSecondary">
                      {course.facultyName}
                    </Typography>
                  </Box>
                  {getApplicationStatus(course)}
                </Box>

                <Typography variant="body2" sx={{ mb: 2 }}>
                  {course.description}
                </Typography>

                <Grid container spacing={1} sx={{ mb: 2 }}>
                  <Grid item xs={6}>
                    <Box display="flex" alignItems="center">
                      <Schedule sx={{ fontSize: 16, mr: 1, color: 'text.secondary' }} />
                      <Typography variant="body2">
                        {course.duration} years
                      </Typography>
                    </Box>
                  </Grid>
                  <Grid item xs={6}>
                    <Box display="flex" alignItems="center">
                      <TrendingUp sx={{ fontSize: 16, mr: 1, color: 'text.secondary' }} />
                      <Typography variant="body2">
                        M{course.tuitionFee?.toLocaleString()}
                      </Typography>
                    </Box>
                  </Grid>
                  <Grid item xs={6}>
                    <Typography variant="body2" color="textSecondary">
                      Applications: {course.stats?.totalApplications || 0}
                    </Typography>
                  </Grid>
                  <Grid item xs={6}>
                    <Typography 
                      variant="body2" 
                      color={course.spotsLeft > 0 ? 'success.main' : 'error.main'}
                    >
                      {course.spotsLeft > 0 ? `${course.spotsLeft} spots left` : 'Course Full'}
                    </Typography>
                  </Grid>
                </Grid>

                {course.qualificationMessage && (
                  <Alert severity="info" sx={{ mb: 2 }}>
                    {course.qualificationMessage}
                  </Alert>
                )}

                <Box display="flex" justifyContent="space-between" alignItems="center">
                  <Typography variant="caption" color="textSecondary">
                    Deadline: {new Date(course.deadline).toLocaleDateString()}
                  </Typography>
                  {getActionButton(course)}
                </Box>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {courses.length === 0 && !loading && (
        <Box textAlign="center" py={4}>
          <School sx={{ fontSize: 64, color: 'text.secondary', mb: 2 }} />
          <Typography variant="h6" color="textSecondary">
            No courses found matching your criteria
          </Typography>
        </Box>
      )}

      {/* Application Dialog */}
      <Dialog open={applyDialogOpen} onClose={() => setApplyDialogOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle>
          Apply for {selectedCourse?.name}
        </DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="textSecondary" gutterBottom>
            {selectedCourse?.instituteName} • {selectedCourse?.code}
          </Typography>
          
          <TextField
            fullWidth
            label="Personal Statement"
            multiline
            rows={4}
            value={applicationData.personalStatement}
            onChange={(e) => setApplicationData({ ...applicationData, personalStatement: e.target.value })}
            sx={{ mt: 2 }}
            placeholder="Explain why you are interested in this course and why you would be a good candidate..."
          />

          <TextField
            fullWidth
            label="Additional Information (Optional)"
            multiline
            rows={2}
            value={applicationData.additionalInfo}
            onChange={(e) => setApplicationData({ ...applicationData, additionalInfo: e.target.value })}
            sx={{ mt: 2 }}
            placeholder="Any additional information you'd like to share..."
          />

          {selectedCourse?.requirements && selectedCourse.requirements.length > 0 && (
            <Alert severity="info" sx={{ mt: 2 }}>
              <Typography variant="subtitle2">Requirements:</Typography>
              <ul>
                {selectedCourse.requirements.map((req, index) => (
                  <li key={index}>{req}</li>
                ))}
              </ul>
            </Alert>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setApplyDialogOpen(false)}>Cancel</Button>
          <Button 
            onClick={handleSubmitApplication} 
            variant="contained"
            disabled={!applicationData.personalStatement.trim()}
          >
            Submit Application
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default StudentCourses;