import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Alert,
  Grid,
  Menu,
  MenuItem
} from '@mui/material';
import {
  Add,
  MoreVert,
  CheckCircle,
  Block,
  School
} from '@mui/icons-material';
import { useAuth } from '../../context/AuthContext';
import api from '../../services/api';

const AdminInstitutions = () => {
  const { user } = useAuth();
  const [institutions, setInstitutions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [dialogOpen, setDialogOpen] = useState(false);
  const [anchorEl, setAnchorEl] = useState(null);
  const [selectedInstitution, setSelectedInstitution] = useState(null);

  const [formData, setFormData] = useState({
    institutionName: '',
    email: '',
    password: '',
    address: '',
    phone: '',
    website: '',
    description: ''
  });

  useEffect(() => {
    fetchInstitutions();
  }, []);

  const fetchInstitutions = async () => {
    try {
      setLoading(true);
      const response = await api.get('/admin/institutions');
      if (response.data.success) {
        setInstitutions(response.data.data.institutions);
      } else {
        setError('Failed to load institutions');
      }
    } catch (err) {
      console.error('Error fetching institutions:', err);
      setError('Error loading institutions');
    } finally {
      setLoading(false);
    }
  };

  const handleMenuOpen = (event, institution) => {
    setAnchorEl(event.currentTarget);
    setSelectedInstitution(institution);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
    setSelectedInstitution(null);
  };

  const handleApprove = async (institutionId) => {
    try {
      const response = await api.post(`/admin/approve/${institutionId}`, {
        type: 'institute'
      });
      if (response.data.success) {
        setSuccess('Institution approved successfully');
        fetchInstitutions();
      }
    } catch (err) {
      setError('Error approving institution');
    }
    handleMenuClose();
  };

  const handleSuspend = async (institutionId, action) => {
    try {
      const response = await api.patch(`/admin/users/${institutionId}/status`, {
        action: action ? 'activate' : 'suspend'
      });
      if (response.data.success) {
        setSuccess(`Institution ${action ? 'activated' : 'suspended'} successfully`);
        fetchInstitutions();
      }
    } catch (err) {
      setError('Error updating institution status');
    }
    handleMenuClose();
  };

  const handleAddInstitution = async () => {
    try {
      const response = await api.post('/admin/institutions', formData);
      if (response.data.success) {
        setSuccess('Institution added successfully');
        setDialogOpen(false);
        setFormData({
          institutionName: '',
          email: '',
          password: '',
          address: '',
          phone: '',
          website: '',
          description: ''
        });
        fetchInstitutions();
      }
    } catch (err) {
      setError('Error adding institution');
    }
  };

  const getStatusChip = (institution) => {
    if (!institution.isApproved) {
      return <Chip label="Pending Approval" color="warning" size="small" />;
    }
    if (!institution.isActive) {
      return <Chip label="Suspended" color="error" size="small" />;
    }
    return <Chip label="Active" color="success" size="small" />;
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <Typography>Loading institutions...</Typography>
      </Box>
    );
  }

  return (
    <Box>
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h4" gutterBottom>
          Manage Institutions
        </Typography>
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={() => setDialogOpen(true)}
        >
          Add Institution
        </Button>
      </Box>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
      {success && <Alert severity="success" sx={{ mb: 2 }}>{success}</Alert>}

      <Card>
        <CardContent>
          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Institution Name</TableCell>
                  <TableCell>Email</TableCell>
                  <TableCell>Courses</TableCell>
                  <TableCell>Applications</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {institutions.map((institution) => (
                  <TableRow key={institution.id}>
                    <TableCell>
                      <Box display="flex" alignItems="center">
                        <School sx={{ mr: 2, color: 'primary.main' }} />
                        <Box>
                          <Typography variant="subtitle1">
                            {institution.institutionName}
                          </Typography>
                          <Typography variant="body2" color="textSecondary">
                            {institution.phone}
                          </Typography>
                        </Box>
                      </Box>
                    </TableCell>
                    <TableCell>{institution.email}</TableCell>
                    <TableCell>
                      <Chip 
                        label={institution.stats?.totalCourses || 0} 
                        variant="outlined" 
                        size="small" 
                      />
                    </TableCell>
                    <TableCell>
                      <Chip 
                        label={institution.stats?.totalApplications || 0} 
                        variant="outlined" 
                        size="small" 
                      />
                    </TableCell>
                    <TableCell>
                      {getStatusChip(institution)}
                    </TableCell>
                    <TableCell>
                      <IconButton
                        size="small"
                        onClick={(e) => handleMenuOpen(e, institution)}
                      >
                        <MoreVert />
                      </IconButton>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </CardContent>
      </Card>

      {/* Add Institution Dialog */}
      <Dialog open={dialogOpen} onClose={() => setDialogOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle>Add New Institution</DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Institution Name"
                value={formData.institutionName}
                onChange={(e) => setFormData({ ...formData, institutionName: e.target.value })}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Email"
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Password"
                type="password"
                value={formData.password}
                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Address"
                value={formData.address}
                onChange={(e) => setFormData({ ...formData, address: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Phone"
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Website"
                value={formData.website}
                onChange={(e) => setFormData({ ...formData, website: e.target.value })}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Description"
                multiline
                rows={3}
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDialogOpen(false)}>Cancel</Button>
          <Button onClick={handleAddInstitution} variant="contained">
            Add Institution
          </Button>
        </DialogActions>
      </Dialog>

      {/* Actions Menu */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleMenuClose}
      >
        {!selectedInstitution?.isApproved && (
          <MenuItem onClick={() => handleApprove(selectedInstitution?.id)}>
            <CheckCircle sx={{ mr: 1 }} />
            Approve
          </MenuItem>
        )}
        <MenuItem onClick={() => handleSuspend(selectedInstitution?.id, !selectedInstitution?.isActive)}>
          <Block sx={{ mr: 1 }} />
          {selectedInstitution?.isActive ? 'Suspend' : 'Activate'}
        </MenuItem>
      </Menu>
    </Box>
  );
};

export default AdminInstitutions;