import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Button,
  Alert
} from '@mui/material';
import {
  TrendingUp,
  People,
  School,
  Business,
  Download
} from '@mui/icons-material';
import { useAuth } from '../../context/AuthContext';
import api from '../../services/api';

const AdminReports = () => {
  const { user } = useAuth();
  const [reportData, setReportData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [reportType, setReportType] = useState('user_registrations');

  const generateReport = async () => {
    try {
      setLoading(true);
      const response = await api.get(`/admin/reports?reportType=${reportType}`);
      if (response.data.success) {
        setReportData(response.data.data);
      } else {
        setError('Failed to generate report');
      }
    } catch (err) {
      console.error('Error generating report:', err);
      setError('Error generating report');
    } finally {
      setLoading(false);
    }
  };

  const StatCard = ({ title, value, subtitle, icon, color = 'primary' }) => (
    <Card>
      <CardContent>
        <Box display="flex" alignItems="center" justifyContent="space-between">
          <Box>
            <Typography color="textSecondary" gutterBottom variant="overline">
              {title}
            </Typography>
            <Typography variant="h4" component="div">
              {value}
            </Typography>
            {subtitle && (
              <Typography variant="body2" color="textSecondary">
                {subtitle}
              </Typography>
            )}
          </Box>
          <Box
            sx={{
              backgroundColor: `${color}.light`,
              borderRadius: '50%',
              p: 1,
              color: 'white',
            }}
          >
            {icon}
          </Box>
        </Box>
      </CardContent>
    </Card>
  );

  return (
    <Box>
      <Typography variant="h4" gutterBottom>
        System Reports
      </Typography>
      <Typography variant="body1" color="textSecondary" gutterBottom>
        Generate and view system analytics and reports
      </Typography>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}

      {/* Report Controls */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Grid container spacing={2} alignItems="center">
            <Grid item xs={12} sm={6} md={4}>
              <FormControl fullWidth>
                <InputLabel>Report Type</InputLabel>
                <Select
                  value={reportType}
                  label="Report Type"
                  onChange={(e) => setReportType(e.target.value)}
                >
                  <MenuItem value="user_registrations">User Registrations</MenuItem>
                  <MenuItem value="application_stats">Application Statistics</MenuItem>
                  <MenuItem value="job_postings">Job Postings</MenuItem>
                  <MenuItem value="system_usage">System Usage</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={6} md={4}>
              <Button
                variant="contained"
                startIcon={<TrendingUp />}
                onClick={generateReport}
                disabled={loading}
                fullWidth
              >
                {loading ? 'Generating...' : 'Generate Report'}
              </Button>
            </Grid>
            <Grid item xs={12} sm={6} md={4}>
              <Button
                variant="outlined"
                startIcon={<Download />}
                fullWidth
              >
                Export Report
              </Button>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* Report Results */}
      {reportData && (
        <Grid container spacing={3}>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard
              title="Total Users"
              value={reportData.summary?.totalUsers || 0}
              icon={<People />}
              color="primary"
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard
              title="Institutions"
              value={reportData.summary?.institutions || 0}
              icon={<School />}
              color="secondary"
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard
              title="Companies"
              value={reportData.summary?.companies || 0}
              icon={<Business />}
              color="success"
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard
              title="Applications"
              value={reportData.summary?.applications || 0}
              icon={<TrendingUp />}
              color="warning"
            />
          </Grid>
        </Grid>
      )}

      {/* Placeholder for when no report is generated */}
      {!reportData && (
        <Card>
          <CardContent sx={{ textAlign: 'center', py: 4 }}>
            <TrendingUp sx={{ fontSize: 64, color: 'text.secondary', mb: 2 }} />
            <Typography variant="h6" gutterBottom>
              No Report Generated
            </Typography>
            <Typography variant="body2" color="textSecondary">
              Select a report type and click "Generate Report" to view analytics
            </Typography>
          </CardContent>
        </Card>
      )}
    </Box>
  );
};

export default AdminReports;