import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Grid,
  Card,
  CardContent,
  Alert,
  LinearProgress
} from '@mui/material';
import {
  Work,
  People,
  TrendingUp,
  Business,
  Schedule
} from '@mui/icons-material';
import { useAuth } from '../../context/AuthContext';
import api from '../../services/api';

const StatCard = ({ title, value, subtitle, icon, color = 'primary' }) => (
  <Card>
    <CardContent>
      <Box display="flex" alignItems="center" justifyContent="space-between">
        <Box>
          <Typography color="textSecondary" gutterBottom variant="overline">
            {title}
          </Typography>
          <Typography variant="h4" component="div">
            {value}
          </Typography>
          {subtitle && (
            <Typography variant="body2" color="textSecondary">
              {subtitle}
            </Typography>
          )}
        </Box>
        <Box
          sx={{
            backgroundColor: `${color}.light`,
            borderRadius: '50%',
            p: 1,
            color: 'white',
          }}
        >
          {icon}
        </Box>
      </Box>
    </CardContent>
  </Card>
);

const CompanyDashboard = () => {
  const { user } = useAuth();
  const [dashboardData, setDashboardData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const response = await api.get('/company/dashboard');
      if (response.data.success) {
        setDashboardData(response.data.data);
      } else {
        setError('Failed to load dashboard data');
      }
    } catch (err) {
      console.error('Error fetching dashboard:', err);
      setError('Error loading dashboard data');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <LinearProgress sx={{ width: '100%' }} />
      </Box>
    );
  }

  if (error) {
    return (
      <Alert severity="error" sx={{ mb: 2 }}>
        {error}
      </Alert>
    );
  }

  if (!dashboardData) {
    return (
      <Alert severity="warning">
        No dashboard data available
      </Alert>
    );
  }

  const { companyInfo, stats, recentApplications } = dashboardData;

  return (
    <Box>
      <Typography variant="h4" gutterBottom>
        Company Dashboard
      </Typography>
      <Typography variant="body1" color="textSecondary" gutterBottom>
        Welcome back, {companyInfo.companyName}
      </Typography>

      {!companyInfo.isApproved && (
        <Alert severity="warning" sx={{ mb: 2 }}>
          Your company account is pending approval. Some features may be limited.
        </Alert>
      )}

      {/* Quick Stats */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Active Jobs"
            value={stats.activeJobs}
            subtitle={`${stats.totalJobs} total`}
            icon={<Work />}
            color="primary"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Applications"
            value={stats.totalApplications}
            subtitle={`${stats.newApplications} new`}
            icon={<People />}
            color="secondary"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Hired"
            value={stats.hiredCandidates}
            subtitle="This period"
            icon={<TrendingUp />}
            color="success"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Shortlisted"
            value={stats.shortlistedCandidates}
            subtitle="For interviews"
            icon={<Business />}
            color="warning"
          />
        </Grid>
      </Grid>

      {/* Recent Applications */}
      {recentApplications && recentApplications.length > 0 && (
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Typography variant="h6" gutterBottom>
              Recent Applications
            </Typography>
            <Grid container spacing={2}>
              {recentApplications.slice(0, 4).map((application) => (
                <Grid item xs={12} sm={6} md={3} key={application.id}>
                  <Card variant="outlined">
                    <CardContent>
                      <Typography variant="subtitle2" gutterBottom>
                        {application.studentName}
                      </Typography>
                      <Typography variant="body2" color="textSecondary" gutterBottom>
                        {application.jobTitle}
                      </Typography>
                      <Box display="flex" justifyContent="space-between" alignItems="center">
                        <Typography variant="caption">
                          Score: {application.qualificationScore}%
                        </Typography>
                        <Typography variant="caption" color="textSecondary">
                          {new Date(application.appliedAt).toLocaleDateString()}
                        </Typography>
                      </Box>
                    </CardContent>
                  </Card>
                </Grid>
              ))}
            </Grid>
          </CardContent>
        </Card>
      )}

      {/* Quick Actions */}
      <Card>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            Quick Actions
          </Typography>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={4}>
              <Card 
                variant="outlined" 
                sx={{ 
                  p: 2, 
                  textAlign: 'center', 
                  cursor: 'pointer',
                  '&:hover': { bgcolor: 'action.hover' }
                }}
                onClick={() => window.location.href = '/company/jobs'}
              >
                <Work sx={{ fontSize: 40, color: 'primary.main', mb: 1 }} />
                <Typography variant="body2">Post New Job</Typography>
              </Card>
            </Grid>
            <Grid item xs={12} sm={4}>
              <Card 
                variant="outlined" 
                sx={{ 
                  p: 2, 
                  textAlign: 'center', 
                  cursor: 'pointer',
                  '&:hover': { bgcolor: 'action.hover' }
                }}
                onClick={() => window.location.href = '/company/applications'}
              >
                <People sx={{ fontSize: 40, color: 'secondary.main', mb: 1 }} />
                <Typography variant="body2">View Applications</Typography>
              </Card>
            </Grid>
            <Grid item xs={12} sm={4}>
              <Card 
                variant="outlined" 
                sx={{ 
                  p: 2, 
                  textAlign: 'center', 
                  cursor: 'pointer',
                  '&:hover': { bgcolor: 'action.hover' }
                }}
                onClick={() => window.location.href = '/company/candidates'}
              >
                <Business sx={{ fontSize: 40, color: 'success.main', mb: 1 }} />
                <Typography variant="body2">Find Candidates</Typography>
              </Card>
            </Grid>
          </Grid>
        </CardContent>
      </Card>
    </Box>
  );
};

export default CompanyDashboard;