import React, { useState, useEffect } from 'react';
import {
  Box,
  Grid,
  Card,
  CardContent,
  Typography,
  Button,
  Chip,
  Alert,
  LinearProgress,
  Tabs,
  Tab,
  Paper,
  Container,
  AppBar,
  Toolbar,
  IconButton,
  Menu,
  MenuItem,
  Badge,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Divider,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow
} from '@mui/material';
import {
  School,
  Business,
  People,
  Notifications,
  Dashboard,
  Assignment,
  AccountCircle,
  ExitToApp,
  TrendingUp,
  Add,
  Pending,
  CheckCircle,
  Cancel
} from '@mui/icons-material';
import { useAuth } from '../../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import api from '../../services/api';

// Tab Panel Component
function TabPanel({ children, value, index, ...other }) {
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`institute-tabpanel-${index}`}
      aria-labelledby={`institute-tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
    </div>
  );
}

const InstituteDashboard = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [tabValue, setTabValue] = useState(0);
  const [dashboardData, setDashboardData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [anchorEl, setAnchorEl] = useState(null);

  useEffect(() => {
    fetchInstituteDashboard();
  }, []);

  const fetchInstituteDashboard = async () => {
    try {
      setLoading(true);
      const response = await api.get('/institute/dashboard');
      if (response.data.success) {
        setDashboardData(response.data.data);
      } else {
        setError('Failed to load dashboard data');
      }
    } catch (err) {
      console.error('Error fetching dashboard:', err);
      setError('Error loading dashboard data');
    } finally {
      setLoading(false);
    }
  };

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };

  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'admitted': return 'success';
      case 'pending': return 'warning';
      case 'rejected': return 'error';
      case 'waiting_list': return 'info';
      default: return 'default';
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <LinearProgress sx={{ width: '100%' }} />
      </Box>
    );
  }

  if (error) {
    return (
      <Alert severity="error" sx={{ mb: 2 }}>
        {error}
      </Alert>
    );
  }

  if (!dashboardData) {
    return (
      <Alert severity="warning">
        No dashboard data available
      </Alert>
    );
  }

  const { instituteInfo, stats, recentApplications, coursesNearingCapacity, courseAdmissionStats } = dashboardData;

  return (
    <Box sx={{ flexGrow: 1 }}>
      <AppBar position="static" sx={{ mb: 3 }}>
        <Toolbar>
          <Typography variant="h6" component="div" sx={{ flexGrow: 1 }}>
            Career Guidance Platform - Institute Portal
          </Typography>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
            <Typography variant="body2">
              {instituteInfo.name}
            </Typography>
            <IconButton color="inherit" onClick={handleMenuOpen}>
              <AccountCircle />
            </IconButton>
            <Menu
              anchorEl={anchorEl}
              open={Boolean(anchorEl)}
              onClose={handleMenuClose}
            >
              <MenuItem onClick={() => { handleMenuClose(); navigate('/profile'); }}>
                <AccountCircle sx={{ mr: 1 }} />
                Profile
              </MenuItem>
              <MenuItem onClick={handleLogout}>
                <ExitToApp sx={{ mr: 1 }} />
                Logout
              </MenuItem>
            </Menu>
          </Box>
        </Toolbar>
      </AppBar>

      <Container maxWidth="xl">
        {/* Welcome Section */}
        <Box sx={{ mb: 4 }}>
          <Typography variant="h4" gutterBottom>
            Welcome, {instituteInfo.name}
          </Typography>
          <Typography variant="body1" color="textSecondary" gutterBottom>
            Institute Management Portal - Manage courses, applications, and admissions
          </Typography>
          
          {!instituteInfo.isApproved && (
            <Alert severity="warning" sx={{ mt: 2 }}>
              Your institute account is pending approval. Some features may be limited.
            </Alert>
          )}

          {instituteInfo.profileComplete !== '100%' && (
            <Alert severity="info" sx={{ mt: 2 }}>
              Your profile is {instituteInfo.profileComplete} complete. 
              <Button 
                color="inherit" 
                size="small" 
                sx={{ ml: 1 }}
                onClick={() => navigate('/profile')}
              >
                Complete your profile
              </Button>
            </Alert>
          )}
        </Box>

        {/* Quick Stats */}
        <Grid container spacing={3} sx={{ mb: 4 }}>
          <Grid item xs={12} sm={6} md={3}>
            <Card>
              <CardContent>
                <Box display="flex" alignItems="center" justifyContent="space-between">
                  <Box>
                    <Typography color="textSecondary" gutterBottom variant="overline">
                      Total Courses
                    </Typography>
                    <Typography variant="h4" component="div">
                      {stats.totalCourses}
                    </Typography>
                    <Typography variant="body2" color="textSecondary">
                      {stats.activeCourses} active
                    </Typography>
                  </Box>
                  <Box sx={{ backgroundColor: 'primary.light', borderRadius: '50%', p: 1, color: 'white' }}>
                    <School />
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={3}>
            <Card>
              <CardContent>
                <Box display="flex" alignItems="center" justifyContent="space-between">
                  <Box>
                    <Typography color="textSecondary" gutterBottom variant="overline">
                      Applications
                    </Typography>
                    <Typography variant="h4" component="div">
                      {stats.totalApplications}
                    </Typography>
                    <Typography variant="body2" color="textSecondary">
                      {stats.pendingApplications} pending
                    </Typography>
                  </Box>
                  <Box sx={{ backgroundColor: 'warning.light', borderRadius: '50%', p: 1, color: 'white' }}>
                    <Assignment />
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={3}>
            <Card>
              <CardContent>
                <Box display="flex" alignItems="center" justifyContent="space-between">
                  <Box>
                    <Typography color="textSecondary" gutterBottom variant="overline">
                      Admitted Students
                    </Typography>
                    <Typography variant="h4" component="div">
                      {stats.admittedApplications}
                    </Typography>
                    <Typography variant="body2" color="textSecondary">
                      {stats.admissionRate}% admission rate
                    </Typography>
                  </Box>
                  <Box sx={{ backgroundColor: 'success.light', borderRadius: '50%', p: 1, color: 'white' }}>
                    <People />
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={3}>
            <Card>
              <CardContent>
                <Box display="flex" alignItems="center" justifyContent="space-between">
                  <Box>
                    <Typography color="textSecondary" gutterBottom variant="overline">
                      Faculties
                    </Typography>
                    <Typography variant="h4" component="div">
                      {stats.totalFaculties}
                    </Typography>
                    <Typography variant="body2" color="textSecondary">
                      Academic departments
                    </Typography>
                  </Box>
                  <Box sx={{ backgroundColor: 'info.light', borderRadius: '50%', p: 1, color: 'white' }}>
                    <Business />
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        {/* Main Content Tabs */}
        <Paper sx={{ width: '100%' }}>
          <Tabs
            value={tabValue}
            onChange={handleTabChange}
            indicatorColor="primary"
            textColor="primary"
            variant="scrollable"
            scrollButtons="auto"
          >
            <Tab icon={<Dashboard />} label="Overview" />
            <Tab icon={<School />} label="Courses" />
            <Tab icon={<Assignment />} label="Applications" />
            <Tab icon={<People />} label="Students" />
            <Tab icon={<Business />} label="Faculties" />
          </Tabs>

          {/* Overview Tab */}
          <TabPanel value={tabValue} index={0}>
            <Grid container spacing={3}>
              {/* Recent Applications */}
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
                      <Typography variant="h6">
                        Recent Applications
                      </Typography>
                      <Button 
                        size="small" 
                        onClick={() => setTabValue(2)}
                      >
                        View All
                      </Button>
                    </Box>
                    {recentApplications && recentApplications.length > 0 ? (
                      <List>
                        {recentApplications.slice(0, 5).map((application, index) => (
                          <React.Fragment key={application.id}>
                            <ListItem>
                              <ListItemIcon>
                                {application.status === 'admitted' && <CheckCircle color="success" />}
                                {application.status === 'pending' && <Pending color="warning" />}
                                {application.status === 'rejected' && <Cancel color="error" />}
                              </ListItemIcon>
                              <ListItemText
                                primary={application.studentName}
                                secondary={
                                  <Box>
                                    <Typography variant="body2" color="textSecondary">
                                      {application.courseName}
                                    </Typography>
                                    <Typography variant="caption" color="textSecondary">
                                      {new Date(application.appliedAt).toLocaleDateString()}
                                    </Typography>
                                  </Box>
                                }
                              />
                              <Chip
                                label={application.status}
                                color={getStatusColor(application.status)}
                                size="small"
                              />
                            </ListItem>
                            {index < recentApplications.length - 1 && <Divider />}
                          </React.Fragment>
                        ))}
                      </List>
                    ) : (
                      <Typography variant="body2" color="textSecondary" sx={{ textAlign: 'center', py: 3 }}>
                        No recent applications
                      </Typography>
                    )}
                  </CardContent>
                </Card>
              </Grid>

              {/* Courses Nearing Capacity */}
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>
                      Courses Nearing Capacity
                    </Typography>
                    {coursesNearingCapacity && coursesNearingCapacity.length > 0 ? (
                      <List>
                        {coursesNearingCapacity.slice(0, 3).map((course, index) => (
                          <React.Fragment key={course.id}>
                            <ListItem>
                              <ListItemText
                                primary={course.name}
                                secondary={
                                  <Box>
                                    <Typography variant="body2" color="textSecondary">
                                      Capacity: {course.currentStudents}/{course.maxStudents} students
                                    </Typography>
                                    <Typography variant="caption" color="textSecondary">
                                      {Math.round((course.currentStudents / course.maxStudents) * 100)}% filled
                                    </Typography>
                                  </Box>
                                }
                              />
                              <Chip
                                label="Nearly Full"
                                color="warning"
                                size="small"
                              />
                            </ListItem>
                            {index < coursesNearingCapacity.length - 1 && <Divider />}
                          </React.Fragment>
                        ))}
                      </List>
                    ) : (
                      <Typography variant="body2" color="textSecondary" sx={{ textAlign: 'center', py: 3 }}>
                        All courses have available capacity
                      </Typography>
                    )}
                  </CardContent>
                </Card>
              </Grid>

              {/* Admission Statistics */}
              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>
                      Admission Statistics by Course
                    </Typography>
                    <TableContainer>
                      <Table>
                        <TableHead>
                          <TableRow>
                            <TableCell>Course Name</TableCell>
                            <TableCell align="right">Total Applications</TableCell>
                            <TableCell align="right">Admitted</TableCell>
                            <TableCell align="right">Admission Rate</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {courseAdmissionStats.map((stat, index) => (
                            <TableRow key={index}>
                              <TableCell>{stat.courseName}</TableCell>
                              <TableCell align="right">{stat.totalApplications}</TableCell>
                              <TableCell align="right">{stat.admitted}</TableCell>
                              <TableCell align="right">{stat.admissionRate}%</TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </TableContainer>
                  </CardContent>
                </Card>
              </Grid>

              {/* Quick Actions */}
              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>
                      Quick Actions
                    </Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={12} sm={4}>
                        <Button
                          fullWidth
                          variant="contained"
                          startIcon={<Add />}
                          onClick={() => setTabValue(1)}
                          sx={{ py: 2 }}
                        >
                          Add New Course
                        </Button>
                      </Grid>
                      <Grid item xs={12} sm={4}>
                        <Button
                          fullWidth
                          variant="outlined"
                          startIcon={<Business />}
                          onClick={() => setTabValue(4)}
                          sx={{ py: 2 }}
                        >
                          Manage Faculties
                        </Button>
                      </Grid>
                      <Grid item xs={12} sm={4}>
                        <Button
                          fullWidth
                          variant="outlined"
                          startIcon={<Assignment />}
                          onClick={() => setTabValue(2)}
                          sx={{ py: 2 }}
                        >
                          Review Applications
                        </Button>
                      </Grid>
                    </Grid>
                  </CardContent>
                </Card>
              </Grid>
            </Grid>
          </TabPanel>

          {/* Other tabs would be implemented similarly */}
          <TabPanel value={tabValue} index={1}>
            <CoursesTab />
          </TabPanel>

          <TabPanel value={tabValue} index={2}>
            <ApplicationsTab />
          </TabPanel>

          <TabPanel value={tabValue} index={3}>
            <StudentsTab />
          </TabPanel>

          <TabPanel value={tabValue} index={4}>
            <FacultiesTab />
          </TabPanel>
        </Paper>
      </Container>
    </Box>
  );
};

// Placeholder components for other tabs
const CoursesTab = () => (
  <Box>
    <Typography variant="h4" gutterBottom>
      Course Management
    </Typography>
    <Typography variant="body1" color="textSecondary" gutterBottom>
      Create and manage courses, set capacities, and track applications
    </Typography>
    <Alert severity="info" sx={{ mb: 3 }}>
      Course management functionality is being implemented. You'll be able to create, edit, and manage courses here.
    </Alert>
  </Box>
);

const ApplicationsTab = () => (
  <Box>
    <Typography variant="h4" gutterBottom>
      Application Management
    </Typography>
    <Typography variant="body1" color="textSecondary" gutterBottom>
      Review student applications, make admission decisions, and manage waiting lists
    </Typography>
    <Alert severity="info" sx={{ mb: 3 }}>
      Application management functionality is being implemented. You'll be able to review and process applications here.
    </Alert>
  </Box>
);

const StudentsTab = () => (
  <Box>
    <Typography variant="h4" gutterBottom>
      Student Management
    </Typography>
    <Typography variant="body1" color="textSecondary" gutterBottom>
      View admitted students and manage student records
    </Typography>
    <Alert severity="info" sx={{ mb: 3 }}>
      Student management functionality is being implemented. You'll be able to view and manage student records here.
    </Alert>
  </Box>
);

const FacultiesTab = () => (
  <Box>
    <Typography variant="h4" gutterBottom>
      Faculty Management
    </Typography>
    <Typography variant="body1" color="textSecondary" gutterBottom>
      Create and manage academic faculties and departments
    </Typography>
    <Alert severity="info" sx={{ mb: 3 }}>
      Faculty management functionality is being implemented. You'll be able to create and manage faculties here.
    </Alert>
  </Box>
);

export default InstituteDashboard;